def tri(n):
    """
    Generate the first n + 1 elements of the Tribonacci sequence.
    """
    if n < 0:
        return []

    result = [1]

    for i in range(1, n + 1):
        if i == 1:
            result.append(3)
        elif i % 2 == 0:
            result.append(1 + i // 2)
        else:
            # For odd i, tri(i) = tri(i-1) + tri(i-2) + tri(i+1)
            # tri(i+1) is tri(even) = 1 + (i+1)/2
            next_even = 1 + (i + 1) // 2
            result.append(result[-1] + result[-2] + next_even)

    return result

