def file_name_check(file_name):
    # Count digits
    digit_count = sum(c.isdigit() for c in file_name)
    if digit_count > 3:
        return 'No'

    # Check for exactly one dot
    if file_name.count('.') != 1:
        return 'No'

    # Split by dot
    parts = file_name.split('.')
    if len(parts) != 2:
        return 'No'

    name_part, extension = parts

    # Check if name part is not empty
    if not name_part:
        return 'No'

    # Check if name part starts with a letter from the latin alphabet
    if not name_part[0].isalpha() or not (name_part[0].islower() or name_part[0].isupper()):
        return 'No'

    # Check if extension is one of the valid ones
    if extension not in ['txt', 'exe', 'dll']:
        return 'No'

    return 'Yes'

